  await swapStatus(api, gh, repo, item, STATUS_RUNNING_AGENT, NEEDS_HUMAN);
  await api.addLabel(gh, repo, item.number, spec.label);
  // A REQUEST ITEM WRITES BACK TO ITS ISSUE, on the one end that is its business
